/* Welche Klasse passt zu diesem Profil? */
function classKey(p) {
  const sp = p.specs || {};
  const hub = sp.displacement || 0;
  if (p.fuel === 'diesel') {
    if (/pumpe.?d(ü|ue)se|\bPD\b/i.test(sp.injection || '') || (p.years && p.years[1] && p.years[1] < 2007)) return 'diesel_pd';
    return (sp.banks > 1 || hub > 2600) ? 'diesel_cr6' : 'diesel_cr4';
  }
  if (/atkinson|hybrid/i.test((p.family || '') + (p.name || ''))) return 'petrol_hybrid';
  if (p.aspiration === 'kompressor') return 'petrol_kompressor';
  if (p.aspiration === 'sauger') return 'petrol_sauger';
  return hub && hub <= 1650 ? 'petrol_turbo_small' : 'petrol_turbo_big';
}
/* Liefert die Sollwerte eines Profils, ergänzt um die Klassenwerte.
   `derived` sagt, welche Werte nicht aus dem Profil stammen. */
function resolveSpecs(p) {
  const base = CLASS_DEFAULTS[classKey(p)] || {};
  const own = p.specs || {};
  const out = Object.assign({}, base, own);
  const derived = [];
  for (const k in base) if (own[k] === undefined) derived.push(k);
  return { specs: out, derived };
}

