/* --- Eigene Profile ---------------------------------------------- */
function customProfiles() {
  const raw = store.get('customProfiles', []);
  return Array.isArray(raw) ? raw.filter(p => p && p.id && p.name) : [];
}
function saveCustomProfile(p) {
  const list = customProfiles().filter(x => x.id !== p.id);
  list.push(p);
  store.set('customProfiles', list);
}
function deleteCustomProfile(id) {
  store.set('customProfiles', customProfiles().filter(x => x.id !== id));
}

/* Sicherung gegen Doppeleinträge: zwei Profile gelten als derselbe Motor, wenn
   Kraftstoff, Aufladung, Hubraum, Leistung und Drehmoment übereinstimmen UND sie
   sich mindestens einen Motorkennbuchstaben teilen. Dann bleibt der reichere von
   beiden stehen — sonst stünde derselbe Motor zweimal in der Auswahl.
   Unterschiedliche Leistungsstufen mit gleichem Kennbuchstaben (bei BMW und
   Mercedes die Regel) bleiben ausdrücklich getrennt. */
function modelTokens(str) {
  return String(str || '').toLowerCase()
    .split(/[,;/]+/).map(t => t.replace(/\b(hybrid|kombi|avant|sportback|limousine|variant|coupé|coupe|cabrio)\b/g, '').trim())
    .filter(t => t.length > 1);
}
function modelsOverlap(a, b) {
  const ta = modelTokens(a), tb = modelTokens(b);
  if (!ta.length || !tb.length) return true;     // ohne Angabe nicht blockieren
  return ta.some(x => tb.some(y => x === y || x.indexOf(y) >= 0 || y.indexOf(x) >= 0));
}
function dedupeProfiles(list) {
  const byKey = new Map();
  const out = [];
  for (const p of list) {
    const sp = p.specs || {};
    if (p.custom || p.generic || !sp.powerPS || !sp.displacement) { out.push(p); continue; }
    const key = [p.fuel, p.aspiration, sp.displacement, sp.powerPS, sp.torqueNm].join('|');
    const codes = (p.engineCode || []).map(c => String(c).toUpperCase().trim());
    const prevList = byKey.get(key);
    let merged = false;
    if (prevList) {
      for (const prev of prevList) {
        const pc = (prev.p.engineCode || []).map(c => String(c).toUpperCase().trim());
        if (!codes.length || !pc.length || !codes.some(c => pc.indexOf(c) >= 0)) continue;
        // Zusätzlich müssen sich die Trägerfahrzeuge überschneiden. Sonst wären etwa
        // die beiden Toyota-Hybridgenerationen zusammengefasst, die denselben
        // Verbrenner in verschiedenen Autos und mit verschiedener Systemleistung haben.
        if (!modelsOverlap(p.models, prev.p.models)) continue;
        // Derselbe Motor: den mit mehr hinterlegten Sollwerten behalten
        const richer = Object.keys(sp).length > Object.keys(prev.p.specs || {}).length ? p : prev.p;
        const other  = richer === p ? prev.p : p;
        const codeUnion = pc.concat(codes).filter((c, i, a) => a.indexOf(c) === i);
        out[prev.i] = Object.assign({}, richer, {
          engineCode: codeUnion,
          years: [Math.min((richer.years || [9999])[0], (other.years || [9999])[0]),
                  Math.max((richer.years || [0, 0])[1] || 0, (other.years || [0, 0])[1] || 0)],
          models: (richer.models || other.models)
        });
        prev.p = out[prev.i];
        merged = true;
        break;
      }
    }
    if (!merged) {
      out.push(p);
      const entry = { p, i: out.length - 1 };
      if (prevList) prevList.push(entry); else byKey.set(key, [entry]);
    }
  }
  return out;
}

/* Der vollständige Katalog: mitgelieferte plus eigene Profile. */
let _profileCache = null;
function allProfiles() {
  const custom = customProfiles().map(p => Object.assign({ custom: true }, p));
  if (!_profileCache) _profileCache = dedupeProfiles(BUILTIN_PROFILES);
  return _profileCache.concat(custom);
}
function profileById(id) {
  if (!id) return null;
  const mapped = LEGACY_PROFILE_IDS[id] || id;
  return allProfiles().find(p => p.id === mapped) || null;
}

/* --- Suche --------------------------------------------------------
   Sucht über Name, Marke, Familie, Motorkennbuchstaben, Trägerfahrzeuge und Baujahr.
   Alle Teilbegriffe müssen treffen, damit „audi 2.0 tdi“ sinnvoll filtert. */
function searchProfiles(query, filters) {
  filters = filters || {};
  const terms = String(query || '').toLowerCase().split(/\s+/).filter(Boolean);
  const scored = [], partial = [];
  for (const p of allProfiles()) {
    if (filters.fuel && p.fuel !== filters.fuel) continue;
    if (filters.aspiration) {
      const a = p.aspiration === 'kompressor' ? 'kompressor' : p.aspiration;
      if (a !== filters.aspiration) continue;
    }
    const sp = p.specs || {};
    /* Gewichtete Felder: ein Treffer im Namen zählt mehr als einer in der Fahrzeugliste */
    const fields = [
      [p.name, 10],
      [p.brand, 8],
      [p.family, 8],
      [(p.engineCode || []).join(' '), 10],
      [p.fuel === 'diesel' ? 'diesel' : 'benzin benziner otto', 5],
      [p.aspiration === 'sauger' ? 'sauger saugmotor' :
       p.aspiration === 'kompressor' ? 'kompressor lader aufgeladen' : 'turbo lader aufgeladen', 4],
      [sp.powerPS ? sp.powerPS + ' ps ' + (sp.powerKW || '') + ' kw' : '', 6],
      [sp.displacement ? (sp.displacement / 1000).toFixed(1) + ' l ' + sp.displacement : '', 5],
      [p.models, 4],
      [p.short, 6]
    ].filter(f => f[0]);
    let score = 0, ok = true, hits = 0;
    for (const t of terms) {
      let best = 0;
      for (const [txt, w] of fields) {
        const i = String(txt).toLowerCase().indexOf(t);
        if (i < 0) continue;
        best = Math.max(best, w + (i === 0 ? 4 : 0));
      }
      if (!best) {
        // Baujahr-Suche: „2014“ trifft jedes Profil, dessen Bauzeitraum das Jahr enthält
        const y = parseInt(t, 10);
        if (y > 1990 && y < 2035 && p.years && y >= p.years[0] && y <= p.years[1]) { score += 4; hits++; continue; }
        ok = false; continue;                // Begriff verfehlt – für den Notnagel weiterzählen
      }
      score += best; hits++;
    }
    if (!hits) continue;
    if (!ok) { partial.push({ p, score: score + hits * 3 - terms.length }); continue; }
    if (p.custom) score += 30;
    if (p.generic) score -= 6;
    if (p.confidence === 'hoch') score += 2;
    else if (p.confidence === 'niedrig') score -= 3;
    scored.push({ p, score });
  }
  const byScore = (a, b) => b.score - a.score || String(a.p.name).localeCompare(String(b.p.name));
  scored.sort(byScore);
  /* Trifft kein Profil alle Begriffe, lieber die besten Teiltreffer zeigen als eine leere Liste */
  if (!scored.length && partial.length) { partial.sort(byScore); return partial.map(x => x.p); }
  return scored.map(x => x.p);
}

/* Nach Marke gruppieren, für die Auswahlliste ohne Suchbegriff */
function profilesByBrand() {
  const map = new Map();
  for (const p of allProfiles()) {
    const b = p.custom ? 'Eigene Profile' : (p.generic ? 'Allgemeine Profile' : (p.brand || 'Sonstige'));
    if (!map.has(b)) map.set(b, []);
    map.get(b).push(p);
  }
  for (const list of map.values())
    list.sort((a, b) => String(a.name).localeCompare(String(b.name)));
  return map;
}

/* Vorbelegung, wenn nichts gewählt und nichts erkannt ist */
function defaultProfile() {
  return profileById('generic_turbo') || BUILTIN_PROFILES[0];
}
